#!/usr/bin/env python3
"""Reviewable tables from original sealed classifications and actual timestamps."""
import argparse,json
from pathlib import Path
R=Path(__file__).resolve().parent
def read(p):return json.loads(p.read_text())
def pct(v):return 'N/A'if v is None else f'{100*v:.2f}%'
def minute(v):return f'{v/60:.2f}'
def fraction(a,b):return f'{a}/{b}'
def make():
 m=read(R/'metrics.json');c=read(R/'costs.json');p=read(R/'pair-metrics.json');product=read(R/'review-product-summary.json');lines=['# Multi-task blind evaluation tables','','Three task pairs; both arms already include v6 contract and observer infrastructure. Null denominators are N/A. F counts below are strict scored failures; confirmed natural product defects are reported separately.','','## Common acceptance','','| Arm | Stage | P | F | U | N/A | U / applicable |','|---|---|---:|---:|---:|---:|---:|']
 for tool,value in m['pooled'].items():
  for stage,r in value['quality'].items():lines.append('| '+ ' | '.join([tool,stage]+[str(r['counts'][s])for s in ['P','F','U','N/A']]+[pct(r['pooledUnassessedRatio'])])+' |')
 lines+=['','## Original descriptor-matched detection ledger','','This is the frozen deterministic strict identity ledger: FP includes expected/unit identity rejection and must not automatically be interpreted as a false product alarm. Independent product dispositions are reported separately below. Conditional ledger rejection=FP/(TP+FP); U is retained, with bounds over all claims. Classical FPR is N/A because no complete true-negative claim universe was labelled. Cluster and row recall here require strict original descriptor-matched independently confirmed product F rows, not every numeric F. Unmapped impressions remain U; explicit successful observations are excluded from the failure-claim denominator.','','| Arm | Origin | TP | FP | U | Detected product rows | Row recall | Detected clusters | Cluster recall | Conditional false discovery | All-claim bounds |','|---|---|---:|---:|---:|---:|---:|---:|---:|---:|---|']
 for tool,value in m['pooled'].items():
  for origin,r in value['detection'].items():lines.append('| '+' | '.join([tool,origin]+[str(r['counts'][s])for s in ['TP','FP','U']]+[fraction(r['detectedProductRows'],r['confirmedProductFailureRows']),pct(r['pooledRowRecall']),fraction(r['detectedProductClusters'],r['confirmedProductClusters']),pct(r['pooledClusterRecall']),pct(r['conditionalFalseDiscoveryRatio']),' – '.join(pct(x)for x in r['allClaimsFalseDiscoveryBounds'])])+' |')
 lines+=['','## Sealed independent product dispositions','','These are integer sums of the original already sealed independent selfreview judgments, not new claim reclassification or a human gold standard. Two grader-labelled false alarms have contradictory original pixel evidence; see [GRADER-DISAGREEMENTS.md](GRADER-DISAGREEMENTS.md). Those labels are preserved, but objectively adjudicated product FDR remains unavailable. Identity-rejected compatible descriptions remain U when a concrete false product alarm is not established. No new detection credit or expected/unit repair is granted. Qualitative/ineligible unknowns are separate. Classical FPR remains N/A.','','| Arm | Origin | TP | Grader-labelled FP | Eligible U | Additional qualitative U | Conditional false discovery | All-claim error bounds |','|---|---|---:|---:|---:|---:|---:|---|']
 for tool,origins in product['pooled'].items():
  for origin,r in origins.items():lines.append('| '+' | '.join([tool,origin]+[str(r['sealedEligibleClaimDispositions'][k])for k in ['TP','FP','U']]+[str(r['additionalQualitativeUnknown']),pct(r['conditionalFalseDiscoveryRatio']),' – '.join(pct(x)for x in r['allClaimErrorBounds'])])+' |')
 lines+=['','Field adapters, exact original source hashes and the identity ledger alongside each task are in [review-product-summary.json](review-product-summary.json). This distinction does not turn a qualitatively related finding into exact descriptor-matched row/cluster credit.','','## Per-task quality and repair','','| Task | Arm | D0 P/F/U/NA | FINAL public P/F/U/NA | FINAL heldout P/F/U/NA | Original combined cluster recall | Public product cluster repair |','|---|---|---|---|---|---:|---:|']
 for task,aliases in m['tasks'].items():
  for alias,r in aliases.items():
   d=r['detection']['combined'];repair=r['repairs'];lines.append('| '+' | '.join([task,r['tool']]+['/'.join(str(r[s]['counts'][x])for x in ['P','F','U','N/A'])for s in ['D0','FINALPublic','FINALHidden']]+[fraction(d['detectedProductClusters'],d['confirmedProductClusters'])+' ('+pct(d['clusterRecall'])+')',fraction(len(repair['resolvedClusters']),repair['confirmedClusters'])+' ('+pct(repair['clusterRepairRate'])+')'])+' |')
 lines+=['','Macro task summaries, platform/class breakdowns, exact missed rows, strict row transitions and new P→F are in [metrics.json](metrics.json). Hidden inputs were unavailable during repair, so they have no D0 hidden repair denominator.','','## Actual end-to-end cost','','The per-unit endpoint is its own FINAL raw corpus seal, including earlier barriers, resource waits and shared experiment scheduling. Complete cohort closure also includes all final typed checks and is reported separately. It is not a production-latency estimate. Native command sums include overlapping iOS/Android work and must not be added as elapsed wall time. Model wall includes compile waits.','','| Task | Arm | Implementation→own FINAL seal (min) | Model phase wall sum (min) | Own native command sum (min) | Waiting/coordination (min) |','|---|---|---:|---:|---:|---:|']
 for unit,r in c['units'].items():lines.append('| '+' | '.join([r['task'],r['tool']]+[minute(r[k])for k in ['continuousImplementationToOwnFinalSealSeconds','modelPhaseWallSumSeconds','ownNativeCommandWallSumSeconds','waitingAndCoordinationSeconds']])+' |')
 lines+=['',f"Cohort first implementation→last public endpoint: **{minute(c['cohortImplementationToPublicEndpointSeconds'])} min**. Complete public cohort closure: **{minute(c['cohortImplementationToCompletePublicCohortSealSeconds'])} min**. Implementation→assignment reveal: **{minute(c['implementationToAssignmentRevealSeconds'])} min**. Preregistration→reveal (including engineering/design/neutral controls): **{minute(c['preregistrationToRevealSeconds'])} min**. Shared audit native command sum: **{minute(c['extraNativeCommandWallSumSeconds'])} min**. Token and money costs are unavailable.",'','## Same-source measurement diagnostic','','| Comparison | Cells | U→assessed | Assessed→U | P↔F conflicts | Before U | After U |','|---|---:|---:|---:|---:|---:|']
 for name in ['collectorSessions','sameFrameCheckers']:
  r=p[name]['pooled'];lines.append('| '+' | '.join([name,str(r['denominator']),str(r['unknownToAssessed']),str(r['assessedToUnknown']),str(r['assessedConflicts']),str(r['aCounts'].get('U',0)),str(r['bCounts'].get('U',0))])+' |')
 lines+=['','Collector sessions compare actual native acquisitions with the same source/public inputs and fixed common oracle. Same-frame checkers run both frozen checkers on identical observation bytes, with zero new SDK calls. These diagnose measurement; they are not extra independent development trials.','','## Limits','','Only three prospective task pairs were tested. Independent AI acceptance is not a human-labelled gold standard. Fixed selected-rule coverage is not complete design-brief coverage. iOS computed typography/color and unsupported evidence remain unknown. Shared device/cache/order/barrier costs prevent a causal speed claim. All strict failures and their separate cause classifications remain published.','']
 return '\n'.join(lines)
def main():
 p=argparse.ArgumentParser();p.add_argument('--write',action='store_true');a=p.parse_args();text=make();out=R/'TABLES.md'
 if a.write:assert not out.exists();out.write_text(text)
 else:assert out.read_text()==text
 print('PASS: tables match original metrics and actual costs')
if __name__=='__main__':main()
